@layer utilities {
  @keyframes spin {
    from {
      transform: rotate(0deg);
    }

    to {
      transform: rotate(360deg);
    }
  }

  @keyframes fadeInGrow {
    0% {
      opacity: 0;
      transform: translateY(-10px) scale(0.95);
    }

    100% {
      opacity: 1;
      transform: translateY(0) scale(1);
    }
  }

  @keyframes fadeOutShrink {
    0% {
      opacity: 1;
      transform: translateY(0) scale(1);
    }

    100% {
      opacity: 0;
      transform: translateY(-10px) scale(0.95);
    }
  }

  @keyframes pulse {
    0%,
    100% {
      opacity: 1;
    }

    50% {
      opacity: 0.5;
    }
  }

  @keyframes accordionDown {
    from {
      height: 0;
    }

    to {
      height: var(--radix-accordion-content-height);
    }
  }

  @keyframes accordionUp {
    from {
      height: var(--radix-accordion-content-height);
    }

    to {
      height: 0;
    }
  }

  .animate-accordionDown {
    animation: accordionDown 0.2s ease-out forwards;
  }

  .animate-accordionUp {
    animation: accordionUp 0.2s ease-out forwards;
  }

  .animate-fadeInGrow {
    animation: fadeInGrow 0.3s ease-out forwards;
  }

  .animate-fadeOutShrink {
    animation: fadeOutShrink 0.3s ease-in forwards;
  }

  .animate-spin {
    animation: spin 1s linear infinite;
  }

  .animate-pulse {
    animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  }
}

